import random
import string
from typing import List

# This generator produces valid initial buffers for FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME
# used by the provided stubs. The stubs sanitize to identifier-like tokens, CSS class
# names, paths starting with '/', JS identifiers, meta header names, and UTF-8 content.
# We therefore craft a compact container format holding multiple ASCII strings that
# are already valid for their respective uses. The fuzzer can slice these as needed.
#
# Format:
#   magic: b'WTG1' (4 bytes)
#   count: 1 byte number of entries N (1..16)
#   Then N entries of: len(1 byte, 1..255) + payload bytes (no NULs needed)
# All payloads are UTF-8, <= 255 bytes each. Total buffer <= 4096 bytes.
# We include a diverse set: localization keys, plural keys, CSS classes, JS identifiers,
# JS class names, HTML attributes, data-* names, internal paths (without leading '/'),
# URLs, symbols, and general UTF-8 text.

ALNUM = string.ascii_letters + string.digits
ID_OK = ALNUM + "_-$"  # for JS identifiers/object names
CLASS_OK = ALNUM + "-_"  # CSS class tokens
KEY_OK = ALNUM + "_.-"   # localization keys
ATTR_OK = ALNUM + "-_:"  # meta/attr names
PATH_OK = ALNUM + "-_/"  # path parts (stub prepends '/')
URL_OK = ALNUM + "-._~:/?#[]@!$&'()*+,;=%"  # permissive URL charset

# Some curated interesting values to trigger code paths
FIXED_KEYS = [
    "k", "items", "hello.world", "menu_File", "a-b_c.d9",
    "Wt_Title", "Wt_QuittedMessage",
]
FIXED_CLASSES = ["app", "main-content", "fuzz_test", "x", "A1_b-2"]
FIXED_JS_IDENTS = ["f", "wtFuzzConn", "App", "_g$", "Symbol$X"]
FIXED_ATTR_NAMES = ["data-fuzz", "data-fuzz-id", "http-equiv", "og:title", "x-meta"]
FIXED_PATHS = ["", "home", "user/profile", "a/b/c", "api_v1", "dash-board"]
FIXED_URLS = [
    "https://cdn.example.com/lib.js",
    "data:text/plain,hello",
    "about:blank",
    "//example.com/a.css",
    "file:///dev/null",
]
FIXED_SYMBOLS = ["$", "jQuery", "_", "S", "MyLib"]
FIXED_TEXTS = [
    "Plain text",
    "<b>XHTML?</b>",
    "emoji \U0001F600",
    "quotes ' \" and backslash \\",
]


def _rand_from_charset(rng: random.Random, charset: str, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(charset) for _ in range(n))


def _make_loc_key(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_KEYS)
    # Start with letter to look nice, include dots/underscores/hyphens
    base = _rand_from_charset(rng, KEY_OK, 1, 24)
    return base


def _make_class(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_CLASSES)
    return _rand_from_charset(rng, CLASS_OK, 1, 24)


def _make_js_ident(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_JS_IDENTS)
    first = rng.choice(string.ascii_letters + "_$")
    rest = _rand_from_charset(rng, ID_OK, 0, 23)
    return first + rest


def _make_attr_name(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_ATTR_NAMES)
    base = _rand_from_charset(rng, ATTR_OK, 3, 16)
    # Prefer data-* style
    if rng.random() < 0.7 and not base.startswith("data-"):
        base = "data-" + base.replace(":", "-")
    return base


def _make_path_part(rng: random.Random) -> str:
    if rng.random() < 0.4:
        return rng.choice(FIXED_PATHS)
    return _rand_from_charset(rng, PATH_OK, 0, 32)


def _make_url(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_URLS)
    scheme = rng.choice(["http", "https"])
    host = _rand_from_charset(rng, string.ascii_lowercase + string.digits + "-", 3, 12)
    tld = rng.choice(["com", "net", "org", "io", "dev"])
    path = _rand_from_charset(rng, string.ascii_lowercase + string.digits + "-_/.", 0, 16)
    if path and not path.startswith("/"):
        path = "/" + path
    return f"{scheme}://{host}.{tld}{path}"


def _make_symbol(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_SYMBOLS)
    return _make_js_ident(rng)


def _make_text(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(FIXED_TEXTS)
    # Generate safe printable text with some punctuation
    chars = string.ascii_letters + string.digits + " .,_-:/?&=#'\"()[]{}"
    return _rand_from_charset(rng, chars, 1, 128)


def _entries_for_seed(rng: random.Random) -> List[bytes]:
    entries: List[bytes] = []

    # Populate a balanced mix to satisfy various stubs
    for _ in range(rng.randint(2, 4)):
        entries.append(_make_loc_key(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(2, 4)):
        entries.append(_make_class(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(1, 3)):
        entries.append(_make_js_ident(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(1, 3)):
        entries.append(_make_attr_name(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(1, 3)):
        entries.append(_make_path_part(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(1, 3)):
        entries.append(_make_url(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(2, 4)):
        entries.append(_make_text(rng).encode('utf-8', 'ignore'))
    for _ in range(rng.randint(1, 2)):
        entries.append(_make_symbol(rng).encode('utf-8', 'ignore'))

    # Also include a compact, syntactically valid JS function body to be used by declareJavaScriptFunction
    body = "function(){/*fuzz body*/}".encode('utf-8')
    entries.append(body)

    # Ensure lengths within 1..255 and total size <= 4096
    trimmed: List[bytes] = []
    total = 4 + 1  # magic + count
    for e in entries:
        if not e:
            e = b"x"
        if len(e) > 255:
            e = e[:255]
        if total + 1 + len(e) > 4096:
            break
        trimmed.append(e)
        total += 1 + len(e)

    # Guarantee at least one entry
    if not trimmed:
        trimmed = [b"k"]

    return trimmed


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    entries = _entries_for_seed(rng)

    # Serialize in the simple container format
    out = bytearray()
    out += b"WTG1"
    out.append(len(entries) & 0xFF)
    for e in entries:
        out.append(len(e) & 0xFF)
        out += e
    return bytes(out)
